import {entropy,classCounts,splitDetails,bestNumericSplit,toyPoints,lloydStep,emStep1D,toyMessages,documentToy,gaussianTerms,practiceCases} from './learning-math.js';
import {predictID3,predictGaussian,predictHeart,predictKNN,multiplyMatrix} from './engines.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(v,n=4)=>Number(v).toFixed(n), pct=v=>f(v*100,2)+'%';
const title=s=>String(s).replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const B='#3264c8',A='#b38b40',P='#8b79af';
let lab,helpers,host,activeId,controller;
const memory={};
const foundations={
 1:['Learn a sequence of questions','Weather conditions','Play: yes or no','A flowchart can answer a new question after learning from examples.'],
 2:['Choose the most plausible class','Measurements of a flower or wine','A class name','Compare how well the measurements fit each learned class.'],
 3:['Recognize a spam message','The words in a document','Ham or spam','Words become evidence for one of two possible answers.'],
 4:['Update a belief using evidence','Related variables in a network','A probability for each target state','Use a diagram and probability tables to combine observations.'],
 5:['Discover similar groups','Measurements without class answers','Cluster memberships','Put similar records together without teaching their species names.'],
 6:['Ask the nearest examples','A new flower and labelled examples','A vote for a species','Examples with similar measurements vote on the answer.'],
 7:['Check how well a model generalizes','A dataset split into five groups','Five sets of evaluation scores','Give every record a turn as an unseen validation example.'],
 8:['Use a cloud notebook','Text cells, code cells and data','Executed code, tables and charts','A notebook keeps an explanation, its program and its results together.']
};
const glossary=[['Example / record','One row describing one case, such as a flower.'],['Feature','An input value, such as petal length.'],['Target / label','The answer in a labelled example, such as its species.'],['Training','Learning rules or parameters from examples.'],['Prediction','Using learned rules for a new input.'],['Testing','Checking predictions on examples kept out of training.'],['Classification','Predicting one of a set of named categories.'],['Clustering','Finding groups when answers are not used for learning.']];
function modelState(id){if(!memory[id]){let saved={};try{saved=JSON.parse(localStorage.getItem('clab-lesson-'+id)||'{}');}catch{}memory[id]={step:0,entropyYes:9,feature:'outlook',branch:'sunny',treeDepth:0,trace:0,traceOutlook:'sunny',traceHumidity:'normal',traceWindy:'False',gaussFeature:0,k:3,fold:1,practice:0,solution:false,matrixDone:false,...saved};}return memory[id];}
function save(){try{localStorage.setItem('clab-lesson-'+activeId,JSON.stringify(modelState(activeId)));}catch{}}
const paragraph=t=>`<p class="learn-prose">${t}</p>`;
const callout=(t,kind='')=>`<div class="learn-callout ${kind}">${t}</div>`;
const formula=(name,text)=>`<details class="learn-formula"><summary>${e(name)} · see the formula</summary><pre>${e(text)}</pre></details>`;
const panel=(heading,body)=>`<section class="learn-visual"><h4>${heading}</h4>${body}</section>`;
const result=(value,label)=>`<div class="learn-number"><strong>${value}</strong><span>${label}</span></div>`;
function flow(items){return `<div class="learn-flow">${items.map((item,i)=>`<div class="learn-flow-box"><span>${String(i+1).padStart(2,'0')}</span><b>${item}</b></div>${i<items.length-1?'<span class="learn-flow-arrow" aria-hidden="true">→</span>':''}`).join('')}</div>`;}
function bars(entries,max=1){return `<div class="learn-bars">${entries.map(([name,value,color=B])=>`<div><div class="learn-bar-label"><span>${e(name)}</span><b>${f(value)}</b></div><div class="learn-bar-track"><i style="width:${Math.max(0,Math.min(100,value/max*100))}%;background:${color}"></i></div></div>`).join('')}</div>`;}
function dots(counts){return `<div class="learn-dot-groups">${Object.entries(counts).map(([name,count],i)=>`<div><strong>${e(name)} <span>${count}</span></strong><div class="learn-dots" role="img" aria-label="${count} ${e(name)} records">${Array.from({length:count},()=>`<i style="background:${[B,A,P][i%3]}"></i>`).join('')}</div></div>`).join('')}</div>`;}
function table(headers,rows){return helpers.dataTable(headers,rows);}
function select(name,label,options,value){return `<label class="learn-field"><span>${label}</span><select data-learn-control="${name}">${options.map(option=>{const [v,l]=Array.isArray(option)?option:[option,title(option)];return `<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(l)}</option>`;}).join('')}</select></label>`;}
function weather(){const d=lab.datasets.weather;return d.rows.map(row=>Object.fromEntries(d.columns.map((name,i)=>[name,typeof row[i]==='boolean'?(row[i]?'True':'False'):row[i]])));}
function splitPanel(rows,feature,target='play',threshold=null){const s=splitDetails(rows,feature,target,threshold),classes=Object.keys(classCounts(rows,target)).sort();return panel('Follow the split calculation',table([feature,...classes,'Records','Entropy','Weight × entropy'],s.subsets.map(g=>[g.value,...classes.map(c=>g.counts[c]||0),g.rows.length,f(g.entropy),`${g.rows.length}/${rows.length} × ${f(g.entropy)} = ${f(g.contribution)}`]))+`<div class="learn-number-row">${result(f(s.parentEntropy),'Before: parent entropy')}${result(f(s.weighted),'After: weighted entropy')}${result(f(s.gain),'Information gain')}</div>`+formula('Information gain',`Weighted entropy = ${s.subsets.map(g=>`(${g.rows.length}/${rows.length} × ${f(g.entropy)})`).join(' + ')}\nInformation gain = ${f(s.parentEntropy)} − ${f(s.weighted)} = ${f(s.gain)}`));}
function growingTree(depth,trace=[]){let nodes=[],edges=[],leaf=0;function place(node,level,parent=null,value=''){const item={node,level,parent,value,x:0,y:45+level*110};nodes.push(item);if(node.attribute===null||level===depth)item.x=75+leaf++*160;else{const children=Object.entries(node.children).map(([v,n])=>place(n,level+1,item,v));item.x=children.reduce((s,c)=>s+c.x,0)/children.length;}if(parent)edges.push(item);return item;}place(lab.models.id3,0);const width=150+(leaf-1)*160;return `<svg class="learn-svg" viewBox="0 0 ${width} ${Math.max(...nodes.map(n=>n.y))+45}" role="img" aria-label="Decision tree revealed to depth ${depth}">${edges.map(n=>{const active=trace.some(p=>p.attribute===n.parent.node.attribute&&p.value===n.value);return `<path d="M${n.parent.x} ${n.parent.y+22} L${n.x} ${n.y-22}" stroke="${active?B:'#b8c6dc'}" stroke-width="${active?4:2}" fill="none"/><rect x="${(n.x+n.parent.x)/2-29}" y="${(n.y+n.parent.y)/2-9}" width="58" height="18" fill="white"/><text x="${(n.x+n.parent.x)/2}" y="${(n.y+n.parent.y)/2+4}" text-anchor="middle" fill="#63748b" font-size="11">${e(n.value)}</text>`;}).join('')}${nodes.map(n=>`<rect x="${n.x-62}" y="${n.y-22}" width="124" height="44" rx="8" fill="${n.node.attribute===null?(n.node.prediction==='yes'?'#eaf1fd':'#fcf3e3'):'#fff'}" stroke="#9fb5d6"/><text x="${n.x}" y="${n.y+5}" text-anchor="middle" font-size="13" fill="#234b85">${n.node.attribute===null?'Play: '+title(n.node.prediction):title(n.node.attribute)}</text>`).join('')}</svg>`;}
function quiz(questions){const state=modelState(activeId);state.answers??={};return `<div class="learn-quiz">${questions.map(([question,options,correct,explanation],i)=>{const chosen=state.answers[i],answered=Number.isInteger(chosen);return `<section><h4>${i+1}. ${question}</h4><div class="learn-answers">${options.map((option,j)=>`<button data-learn-quiz="${i}" data-answer="${j}" aria-pressed="${chosen===j}" class="${chosen===j?(j===correct?'correct':'incorrect'):''}">${e(option)}</button>`).join('')}</div>${answered?`<p class="learn-feedback ${chosen===correct?'correct':'incorrect'}" role="status"><b>${chosen===correct?'Correct.':'Try again.'}</b> ${explanation}</p>`:''}</section>`;}).join('')}<div class="learn-next-links"><button class="button primary" data-tab="interactive">Try the experiment →</button><button class="button" data-tab="program">See the Python program</button><button class="button" data-tab="output">Review the actual output</button></div></div>`;}
const q1=[['Which column is the answer we want to predict?',['outlook','play','humidity'],1,'The target is play. The other columns provide input features.'],['Which feature becomes the root?',['The first column','The one with highest information gain','The longest name'],1,'Compare gains at the current node. Outlook removes the most uncertainty here.'],['What is the entropy of a pure group?',['0','1','14'],0,'When all labels agree, there is no uncertainty left.']];
function practice(){const s=modelState(1),p=practiceCases[s.practice];let body=select('practice','Choose a practice pattern',practiceCases.map((p,i)=>[i,p.title]),s.practice)+callout('Adapted from the six question patterns in your revision PDF. Counts and answers are recomputed from the tables. Paper/session attributions in the guide have not been independently authenticated.');if(p.concept){body+=flow(['Describe labelled examples','Choose questions using gain','Create branches','Predict at a leaf'])+paragraph('In the weather tree, an overcast day gives Yes immediately. For a sunny day, ask about humidity: normal gives Yes; high gives No. Temperature is not needed on that path.');}else{const details=p.features.map(feature=>p.numeric?.includes(feature)?bestNumericSplit(p.rows,feature,p.target):splitDetails(p.rows,feature,p.target));const best=Math.max(...details.map(d=>d.gain)),winners=details.filter(d=>Math.abs(d.gain-best)<1e-10);body+=table([...p.features,p.target],p.rows.map(r=>[...p.features.map(k=>r[k]),r[p.target]]))+`<button class="button" data-learn-action="solution">${s.solution?'Hide':'Reveal'} worked answer</button>`;if(s.solution)body+=paragraph(`Parent entropy: <b>${f(details[0].parentEntropy)} bits</b>.`)+table(['Feature / test','Weighted entropy','Gain'],details.map(d=>[d.feature+(d.threshold===null?'':` ≤ ${d.threshold}`),f(d.weighted),f(d.gain)]))+callout(`Best split${winners.length>1?'s (tie)':''}: <b>${winners.map(d=>e(d.feature)+(d.threshold===null?'':` ≤ ${d.threshold}`)).join(' or ')}</b>. The largest gain is ${f(best)}.`);if(p.note)body+=callout(e(p.note));if(s.practice===5&&s.solution)body+=multiclassPractice();}return `<details class="learn-practice" ${s.practiceOpen?'open':''}><summary>More ID3 practice · six question patterns + an extra dataset</summary><div>${body}</div></details>`;}
function multiclassPractice(){const before=entropy([100,150,750]),blond=entropy([100,50,250]),other=entropy([0,100,500]),remaining=.4*blond+.6*other;return panel('Bonus: entropy works for three classes too',table(['Group','Professors','Staff','Students','Entropy'],[['Parent',100,150,750,f(before)],['Blond',100,50,250,f(blond)],['Not blond',0,100,500,f(other)]])+paragraph(`Weighted entropy = (400/1000 × ${f(blond)}) + (600/1000 × ${f(other)}) = ${f(remaining)}. Information gain = ${f(before)} − ${f(remaining)} = <b>${f(before-remaining)} bits</b>.`)+callout('Entropy can exceed 1 bit when there are more than two classes. The zero professor count in the not-blond group contributes zero to entropy.'));}
function id3Steps(){const rows=weather(),s=modelState(1);return [
 ['Meet the problem','Teach a flowchart using examples','You already make decisions by asking questions. ID3 learns which question to ask first from examples with known answers.',()=>flow(['Read the weather','Ask a useful question','Choose a matching branch','Reach Yes or No'])+panel('Features are inputs; the target is the answer',table(['Outlook','Temperature','Humidity','Windy','play · TARGET'],rows.slice(0,5).map(r=>[r.outlook,r.temperature,r.humidity,r.windy,r.play])))+callout('Supervised learning means the training examples include the correct answers. Classification means the answer is a category, here Yes or No.')],
 ['Count the answers','First, understand the 14 examples','There are 9 Yes answers and 5 No answers. Before choosing a question, measure how mixed those answers are.',()=>dots({Yes:9,No:5})+`<div class="learn-number-row">${result('9 / 14 = 0.6429','Proportion of Yes')}${result('5 / 14 = 0.3571','Proportion of No')}</div>`+callout('Do not use the id column as a useful weather feature. It only identifies a row.')],
 ['Feel uncertainty','Entropy is a measure of mixed answers','A group containing only Yes needs no more questions. A group evenly split between Yes and No is harder to decide. Move the slider to feel the difference.',()=>`<label class="learn-field"><span>Sandbox: number of Yes answers, out of 14</span><input type="range" min="0" max="14" value="${s.entropyYes}" data-learn-control="entropyYes"></label><div id="entropy-live">${entropySandbox()}</div>`+formula('Binary entropy','H = −p(Yes) log₂ p(Yes) − p(No) log₂ p(No)\nTreat a zero-count term as 0. Entropy is measured in bits.')+callout('This slider is an illustration. The training dataset still has 9 Yes and 5 No. For two classes the maximum is 1 bit; for more classes the maximum is log₂(number of classes).')],
 ['Try a question','Split the records by a feature','Choose a feature. Each answer creates a smaller group. Count its labels, calculate its entropy, and weight that entropy by the group size.',()=>select('feature','Question to test',['outlook','humidity','windy','temperature'],s.feature)+splitPanel(rows,s.feature)+callout('Weights matter: a group with ten records must count more than a group with one record. The weighted remaining entropy combines all groups fairly.')],
 ['Choose the root','Ask the question that removes most uncertainty','Calculate the information gain for every available feature. The largest gain gives the first question, called the root.',()=>{const gains=['outlook','humidity','windy','temperature'].map(k=>[title(k),splitDetails(rows,k).gain]);return bars(gains,.3)+callout('Outlook wins: 0.9403 − 0.6935 ≈ 0.2467 bits. “Best” means best among the candidate features at this node, not a guarantee of a globally optimal tree.');}],
 ['Repeat in a branch','Ask another question only if needed','An overcast group already has only Yes answers. Sunny and rainy groups are mixed, so repeat the same calculation within each smaller group.',()=>{const group=rows.filter(r=>r.outlook===s.branch);const best=s.branch==='sunny'?'humidity':'windy';return select('branch','Inspect an outlook branch',['sunny','overcast','rainy'],s.branch)+dots(classCounts(group,'play'))+(s.branch==='overcast'?callout('4 Yes, 0 No → entropy 0 → stop and create a Yes leaf.'):splitPanel(group,best)+callout(`Within ${s.branch}, ${best} separates the labels completely. Gains are recalculated on this subset, not copied from the original dataset.`));}],
 ['Grow the tree','A root, branches and leaves','Reveal the tree one level at a time. A question is an internal node. An answer labels a branch. A leaf stores a class.',()=>select('treeDepth','Tree depth to reveal',[[0,'1 · Root only'],[1,'2 · Outlook branches'],[2,'3 · Complete tree']],s.treeDepth)+panel('Decision tree under construction',growingTree(Number(s.treeDepth)))+callout('Stop when a subset is pure or no features remain. With no features left, the program uses the local majority class. For an unseen value at prediction time it also uses that node’s majority class. Zero gain at one level does not always mean later features are useless.')],
 ['Trace a prediction','Follow one path, one decision at a time','Change the new example, then advance through its path. The tree may not need every input feature to reach an answer.',()=>traceLesson()],
 ['Check your understanding','Explain it before reading the program','Answer these quick questions, then explore the full interactive experiment or its Python implementation.',()=>quiz(q1)+practice()]
 ];}
function entropySandbox(){const yes=Number(modelState(1).entropyYes),no=14-yes,h=entropy([yes,no]);return dots({Yes:yes,No:no})+`<div class="learn-number-row">${result(f(h),'Entropy in bits')}${result(yes===0||no===0?'Pure':yes===7?'Most mixed':'Mixed','What the group feels like')}</div>`+bars([['Uncertainty',h]],1);}
function traceLesson(){const s=modelState(1),sample={outlook:s.traceOutlook,humidity:s.traceHumidity,windy:s.traceWindy,temperature:'hot'},r=predictID3(lab.models.id3,sample);s.trace=Math.min(s.trace,r.path.length);return `<div class="learn-controls">${select('traceOutlook','Outlook',['sunny','overcast','rainy'],s.traceOutlook)}${select('traceHumidity','Humidity',['high','normal'],s.traceHumidity)}${select('traceWindy','Windy',['False','True'],s.traceWindy)}</div>`+panel('The path so far',growingTree(2,r.path.slice(0,s.trace)))+`<div class="learn-trace" aria-live="polite">${s.trace===0?'Start at the root: ask about outlook.':r.path.slice(0,s.trace).map((p,i)=>`<p><b>${i+1}.</b> ${e(title(p.attribute))} = ${e(p.value)}</p>`).join('')}${s.trace===r.path.length?`<strong>Leaf reached → Play: ${title(r.label)}</strong>`:''}</div><div class="learn-controls"><button class="button" data-learn-action="trace-reset">Start again</button><button class="button primary" data-learn-action="trace-next" ${s.trace>=r.path.length?'disabled':''}>Next decision →</button></div>`+callout('For Sunny → Normal, only outlook and humidity are checked. Temperature and windy do not affect this particular path.');}
function gaussianCurve(model,feature){const means=model.means.map(r=>r[feature]),vars=model.variances.map(r=>r[feature]);const lo=Math.min(...means.map((m,i)=>m-3*Math.sqrt(vars[i]))),hi=Math.max(...means.map((m,i)=>m+3*Math.sqrt(vars[i]))),pdf=(x,k)=>Math.exp(-((x-means[k])**2)/(2*vars[k]))/Math.sqrt(2*Math.PI*vars[k]);const ymax=Math.max(...vars.map(v=>1/Math.sqrt(2*Math.PI*v)));let paths='';for(let k=0;k<3;k++){const points=Array.from({length:101},(_,i)=>{const x=lo+(hi-lo)*i/100;return `${55+i*4.5},${235-pdf(x,k)/ymax*180}`;});paths+=`<polyline points="${points.join(' ')}" fill="none" stroke="${[B,A,P][k]}" stroke-width="3"/>`;}
 const x=model.defaults[feature],px=55+(x-lo)/(hi-lo)*450;return `<svg viewBox="0 0 560 285" class="learn-svg" role="img" aria-label="Gaussian density curves for the three flower classes"><line x1="55" y1="235" x2="510" y2="235" stroke="#a7b9d4"/>${paths}<line x1="${px}" y1="30" x2="${px}" y2="235" stroke="#172b4d" stroke-dasharray="5 4"/><text x="${px}" y="20" text-anchor="middle" font-size="12">New value: ${x}</text><text x="55" y="255" font-size="12">${f(lo,1)}</text><text x="475" y="255" font-size="12">${f(hi,1)}</text><text x="280" y="280" text-anchor="middle" font-size="12">${e(model.features[feature])}</text></svg>`+`<div class="learn-legend">${model.classes.map((c,i)=>`<span style="color:${[B,A,P][i]}">● ${e(c)}</span>`).join('')}</div>`;}
function splitGrid(training,test,total=training+test){return `<div class="learn-split-grid" role="img" aria-label="${training} training and ${test} held-out records">${Array.from({length:total},(_,i)=>`<i class="${i<training?'train':'test'}"></i>`).join('')}</div><div class="learn-legend"><span style="color:${B}">● Training: ${training}</span><span style="color:${A}">● Held out: ${test}</span></div>`;}
function nbSteps(){const s=modelState(2),m=lab.models.gaussian.iris,terms=gaussianTerms(m,m.defaults),r=predictGaussian(m,m.defaults);return [
 ['Meet a flower','Use measurements to choose a species','An Iris flower has four measured lengths and widths. Its species is the label. The model compares three possible species.',()=>flow(['Four measurements','Compare learned classes','Predict a species'])+table(['Feature','New value (cm)'],m.features.map((name,i)=>[name,m.defaults[i]]))],
 ['Keep a fair test','Learn from 120 flowers; hide 30','The model may see the 120 training labels. Keep the other 30 flowers out of learning so they can test whether the rules work on unseen examples.',()=>splitGrid(120,30)+callout('Stratified means each class keeps a similar share in both groups. Any missing-value replacements must also be learned from training rows only.')],
 ['Start with a prior','What is common before seeing measurements?','A prior is the starting class proportion. Here the stratified training set has 40 examples of each species, so every class starts with probability 1/3.',()=>bars(terms.map(t=>[t.label,t.prior]),1)+formula('Class prior','P(class) = training examples in class / all training examples\nP(setosa) = 40 / 120 = 0.3333')],
 ['Learn each class shape','A mean is the center; variance is the spread','Gaussian Naive Bayes summarizes each numeric feature in each class with a bell-shaped curve. A measurement near a class center often has a higher density for that class.',()=>select('gaussFeature','Measurement to inspect',m.features.map((name,i)=>[i,name]),s.gaussFeature)+gaussianCurve(m,Number(s.gaussFeature))+table(['Class','Training mean','Training variance'],m.classes.map((c,i)=>[c,f(m.means[i][s.gaussFeature]),f(m.variances[i][s.gaussFeature])]))+callout('The vertical axis is a probability density, not the probability of an exact numeric value. The bell shape is a modelling assumption, not a guarantee about nature.')],
 ['Combine the evidence','Add the log scores from all four features','“Naive” means the model treats features as conditionally independent once the class is known. It combines one likelihood per feature with the prior. Logs let the program add scores instead of multiplying tiny values.',()=>table(['Class','Log prior',...m.features.map((_,i)=>'Feature '+(i+1)), 'Total log score'],terms.map(t=>[t.label,f(t.logPrior),...t.terms.map(v=>f(v)),f(t.total)]))+formula('Gaussian scoring','log score(class) = log P(class) + sum of log densities\nlog density = −0.5 × [log(2π × variance) + (x − mean)² / variance]')+callout('A small positive variance floor prevents division by zero for constant features. Direct log-density calculations avoid numerical underflow.')],
 ['Choose a class','The largest combined score wins','Normalize the scores to compare their relative sizes. Then choose the class with the greatest value.',()=>bars(m.classes.map((c,i)=>[c,r.probabilities[i]]))+callout(`<b>Prediction: ${e(r.label)}.</b> The class attached to this held-out example is ${e(lab.datasets.iris.rows[m.testRows[0]][4])}. Normalized Naive Bayes scores are not guaranteed to be calibrated probabilities.`)],
 ['Evaluate on unseen rows','Accuracy counts correct predictions','Repeat prediction for all 30 test flowers. The captured Iris run gets 29 right and 1 wrong. Wine is a second, separate numerical dataset in the program.',()=>flow(['29 correct predictions','Divide by 30 test records','Accuracy = 96.67%'])+helpers.confusion(m.matrix,m.classes)+callout('Accuracy = correct predictions / all predictions. Never report training accuracy as if it measures unseen-data performance.')],
 ['Check your understanding','Connect the idea to the program','You can now explain a prior, a class likelihood, and why the data is split.',()=>quiz([['When should the model see test labels?',['During fitting','Only when checking predictions'],1,'The test labels are answers reserved for evaluation.'],['What does Gaussian NB learn for each class?',['Means, variances and priors','A list of decision-tree questions'],0,'Numeric distributions summarize each feature within each class.'],['What does the largest score tell us?',['Which class this model prefers','That the prediction is certain'],0,'Model scores rank the classes; they do not prove that the answer is correct.']])]
 ];}
function docSteps(){const toy=documentToy();return [
 ['Words are clues','Start with a tiny document collection','Ham means an ordinary message; spam means an unwanted promotional message. The six messages below are a small teaching example, not the full SMS dataset.',()=>table(['Label','Training message'],toyMessages.map(r=>[r.label,r.text]))+callout('The real program uses 5,159 unique usable SMS records after cleaning. Our miniature example makes every word count easy to inspect.')],
 ['Clean and separate','Keep duplicates out of the test boundary','Empty messages and inconsistent labels do not help the model. Identical messages should not appear in both training and test sets, because that would make evaluation look easier than it is.',()=>flow(['Validate labels and text','Remove conflicting / repeated messages','Split 4,127 train / 1,032 test','Fit vocabulary on training only'])],
 ['Turn text into counts','A computer needs numbers, not a sentence','Lowercase FREE prize! and split it into words. A vocabulary is the list of words known from training. Word order is ignored in this bag-of-words model.',()=>flow(['FREE prize!','free · prize','Counts: free=1, prize=1'])+table(['Known word','Count in new message'],toy.vocabulary.map(w=>[w,toy.tokens.filter(x=>x===w).length]))],
 ['Start with priors','Three ham and three spam examples','Before reading a word, each class has prior probability 3/6. The next step asks how often each message word appears inside each class.',()=>bars([['ham prior',.5],['spam prior',.5]])+formula('Bayes rule','P(class | words) is proportional to P(class) × P(words | class)\nWith conditional independence: use one word likelihood per token.')],
 ['Avoid a zero score','Add one before dividing','A word might never occur in one class. Without smoothing, one zero can erase the entire class score. Laplace smoothing adds one to every vocabulary word count.',()=>table(['Word','Ham count','Spam count','P(word | ham)','P(word | spam)'],toy.tokens.map(w=>[w,toy.counts.ham[w],toy.counts.spam[w],`(${toy.counts.ham[w]}+1)/19`, `(${toy.counts.spam[w]}+1)/19`]))+formula('Laplace smoothing','P(word | class) = (word count in class + 1) / (all class tokens + vocabulary size)\nEach class has 9 tokens; vocabulary size = 10; denominator = 19.')],
 ['Combine the word clues','A message with free and prize favors spam','For our toy example, multiply the prior by the two smoothed word probabilities. Normalize the two scores so their relative sizes are easy to compare.',()=>table(['Class','Unnormalized score','Normalized score'],[['ham','0.5 × (1/19) × (1/19)',pct(toy.probabilities[0])],['spam','0.5 × (3/19) × (3/19)',pct(toy.probabilities[1])]])+bars(toy.classes.map((c,i)=>[c,toy.probabilities[i]]))+callout('The toy model prefers spam (90%). Repeated words contribute repeated factors. Unknown words are ignored by the real fitted vocabulary; the program uses log scores for stability.')],
 ['Read the real result','Accuracy and recall answer different questions','Return to the actual SMS run. The model found 116 spam messages, missed 12 spam messages and incorrectly flagged 4 ordinary messages.',()=>helpers.confusion([[900,4],[12,116]],['ham','spam'])+table(['Metric','Calculation','Meaning'],[['Accuracy','(900+116)/1032 = 98.45%','Correct messages overall'],['Spam precision','116/(116+4) = 96.67%','How often a spam flag was right'],['Spam recall','116/(116+12) = 90.62%','How much actual spam was found']])],
 ['Check your understanding','Explain what happens to a new message','The vocabulary and word statistics come from training documents. The real experiment uses Multinomial, not Gaussian, Naive Bayes.',()=>quiz([['Why turn words into counts?',['To represent documents numerically','To sort the document alphabetically'],0,'Word counts form the numeric features used by Multinomial NB.'],['Why add one to word counts?',['To stop zero-frequency words from erasing a score','To guarantee 100% accuracy'],0,'Smoothing handles unseen word/class combinations; it does not guarantee correct predictions.'],['Which documents define the vocabulary?',['Training documents only','Training and test documents together'],0,'Using test documents to learn vocabulary would leak test information into preprocessing.']])]
 ];}
function bnSteps(){const m=lab.models.heart,r=predictHeart(m,m.defaultRaw),cuts=m.rules.age.cut_points,age=m.defaultRaw.age;return [
 ['Think in related events','A network connects variables','A Bayesian network is a directed graph with no directed cycles. Each variable has a probability table conditioned on its parents. Start with a simple hypothetical weather example before looking at heart data.',()=>flow(['Rain','Wet road'])+callout('The arrow here says our example models wet-road probability using rain. A learned arrow in a dataset does not, by itself, establish a causal relationship.')],
 ['Read a probability table','A conditional probability adds a condition','P(wet | rain) means the chance of a wet road in cases where rain is known. These illustrative probabilities are made up for learning.',()=>table(['Quantity','Probability','Out of 100 hypothetical cases'],[['Rain',.2,'20 rain cases'],['No rain',.8,'80 no-rain cases'],['Wet given rain',.8,'16 of the 20 rain cases'],['Wet given no rain',.1,'8 of the 80 no-rain cases']])+bars([['Starting rain probability',.2],['Wet if rain',.8],['Wet if no rain',.1]])],
 ['Combine related events','Multiply along the network factorization','The probability of rain AND a wet road is the rain probability multiplied by wet-given-rain. Do the same for no rain.',()=>table(['Explanation','Calculation','Probability'],[['Rain and wet','0.2 × 0.8',.16],['No rain and wet','0.8 × 0.1',.08],['Wet, either way','0.16 + 0.08',.24]])+formula('Joint factorization','P(Rain, Wet) = P(Rain) × P(Wet | Rain)\nIn a larger network: multiply one conditional table factor per node.')],
 ['Update after evidence','A wet road changes the rain belief','Among 24 wet-road cases, 16 are rain cases. Observing wetness raises the rain probability from 20% to 16/24, approximately 66.67%. It does not prove that rain occurred.',()=>flow(['Prior: rain 20%','Observe: road is wet','Posterior: rain 66.67%'])+bars([['Before observing wet',.2],['After observing wet',16/24]])+formula('Posterior probability','P(Rain | Wet) = P(Rain and Wet) / P(Wet)\n= 0.16 / 0.24 = 0.6667')],
 ['Prepare the heart data','Turn measurements into supported states','The real experiment uses 13 predictors and a binary target. It learns missing-value replacements and numeric bin boundaries from the training split only.',()=>panel('An actual age measurement becomes a discrete state',flow([`Age = ${age}`,`Training cuts: ${cuts.map(x=>f(x,1)).join(', ')}`,`State = ${r.evidence.age}`]))+table(['Age range','State'],[[`age < ${cuts[0]}`,0],[`${cuts[0]} ≤ age < ${cuts[1]}`,1],[`age ≥ ${cuts[1]}`,2]])+callout('A state is a category used in the probability table. The target is excluded from prediction evidence. Original UCI categorical codes must match the program’s data contract.')],
 ['Learn a larger network','Use training data to find a structure and its tables','The program searches for a network structure using a discrete score, limits each node to two parents, and estimates smoothed conditional probability tables.',()=>`<figure class="learn-figure"><img src="assets/heart_network.png" alt="The fitted 14-node Bayesian network for Cleveland data"></figure>`+paragraph('For inference, the program combines the relevant conditional factors. Variables not observed are summed out; observed values restrict the factors. This is called variable elimination.')+callout('The two-node weather example explains probability updating. It is not the trained heart network, and its invented numbers are not medical statistics.')],
 ['Inspect a real posterior','Compare the two possible target states','For the first held-out record, the trained network produces these model probabilities after preprocessing its evidence.',()=>bars([['Target 0 · absence',r.probabilities[0]],['Target 1 · presence',r.probabilities[1]]])+callout(`The larger value gives target ${r.label}. On all 61 held-out records the model gets 53 correct: 86.89% accuracy. These are educational dataset predictions, not clinically validated diagnoses.`,'caution')],
 ['Check your understanding','Keep evidence and the answer separate','You have seen a prior, a conditional table, and a posterior, and how a simple idea extends to the full network.',()=>quiz([['What does P(Wet | Rain) mean?',['Probability of wetness when rain is known','Probability of rain when wetness is known'],0,'The event after the bar is the condition. Reversing the direction requires Bayes rule.'],['Does a learned arrow prove a cause?',['Yes','No'],1,'The graph represents a statistical factorization; causal interpretation needs additional assumptions.'],['Should the known target be included as evidence when predicting it?',['Yes','No'],1,'That would reveal the answer and invalidate the prediction exercise.']])]
 ];}
function clusterDrawing(centers,labels=null){const points=toyPoints;return `<svg class="learn-svg" viewBox="0 0 550 310" role="img" aria-label="Six teaching points and two cluster centers">${[0,2,4,6,8].map(n=>`<line x1="50" y1="${270-n*27}" x2="500" y2="${270-n*27}" stroke="#edf1f7"/><text x="30" y="${274-n*27}" font-size="12">${n}</text>`).join('')}${points.map((p,i)=>`<circle cx="${50+p[0]*50}" cy="${270-p[1]*27}" r="8" fill="${labels?[B,A][labels[i]]:'#b8c8e3'}"/><text x="${65+p[0]*50}" y="${274-p[1]*27}" font-size="11">${String.fromCharCode(65+i)}</text>`).join('')}${centers.map((p,k)=>`<g stroke="${[B,A][k]}" stroke-width="4"><path d="M${42+p[0]*50} ${262-p[1]*27}l16 16m0-16-16 16"/><text x="${50+p[0]*50}" y="${249-p[1]*27}" text-anchor="middle" font-size="12" stroke="none" fill="${[B,A][k]}">Center ${k+1}</text></g>`).join('')}<text x="270" y="302" font-size="12" text-anchor="middle">Illustrative two-dimensional coordinates</text></svg>`;}
function clusterSteps(){const initial=[[1,1],[8,8]],first=lloydStep(toyPoints,initial),next=lloydStep(toyPoints,first.next),emModel={means:[2,6],variances:[4,4],weights:[.5,.5]},em=emStep1D(toyPoints.map(p=>p[0]),emModel);return [
 ['Find groups, not labels','Similar records can form clusters','Unlike classification, clustering does not use species labels for learning. We will first group six made-up points into two clusters, then connect the idea to Iris.',()=>clusterDrawing([])+callout('This two-dimensional, two-cluster example is for teaching. The actual experiment fits three clusters using all four standardized Iris measurements.')],
 ['Choose starting centers','K means the number of groups','K-Means starts with K centers. A center is a representative position for a cluster. Here K=2, with initial centers at (1,1) and (8,8).',()=>clusterDrawing(initial)+formula('Euclidean distance','distance(point, center) = √[(x − center_x)² + (y − center_y)²]')],
 ['Assign each point','The nearest center wins','Calculate the squared distance to both centers. The nearer center gets the point; the square root is unnecessary when only comparing distances.',()=>clusterDrawing(initial,first.labels)+table(['Point','Coordinates','Squared distance to C1','Squared distance to C2','Cluster'],toyPoints.map((p,i)=>[String.fromCharCode(65+i),p.join(', '),p.reduce((s,x,j)=>s+(x-initial[0][j])**2,0),p.reduce((s,x,j)=>s+(x-initial[1][j])**2,0),first.labels[i]+1]))],
 ['Move the centers','A mean becomes the new representative','Average the coordinates of the points in each group. Repeat assignment and averaging until the centers or assignments stop changing enough.',()=>clusterDrawing(first.next,next.labels)+table(['Cluster','New center','Why'],first.next.map((c,k)=>[k+1,c.map(x=>f(x,3)).join(', '),'Average the three assigned points']))+`<div class="learn-number-row">${result(f(first.sse),'Squared error before move')}${result(f(next.sse),'Squared error after move')}</div>`+callout('Lower within-cluster squared error means points are closer to their assigned centers. In this example the next assignment is unchanged. Real K-Means can settle in different local solutions, so the program tries repeated initializations.')],
 ['EM: allow uncertainty','A point can partially belong to both groups','A Gaussian mixture represents each cluster with a mean, variance/covariance, and weight. The E-step calculates responsibilities: how much each component accounts for a point.',()=>table(['Point x · teaching 1D example','Responsibility for component 1','Responsibility for component 2'],toyPoints.map((p,i)=>[p[0],pct(em.responsibilities[i][0]),pct(em.responsibilities[i][1])]))+callout('Here we use x only, with means 2 and 6, variances 4 and 4, and equal weights. Responsibilities in each row sum to 100%. The real experiment uses four-dimensional full covariance matrices.')+formula('E-step','responsibility(component k, point x)\n= weight_k × GaussianDensity_k(x) / sum of all weighted densities')],
 ['EM: update the mixture','The M-step uses weighted averages','Each point contributes to every component according to its responsibility. Update the means, variances and mixture weights, then return to the E-step.',()=>table(['Parameter','Component 1','Component 2'],[['Effective number of points',...em.totals.map(x=>f(x))],['Updated mean',...em.next.means.map(x=>f(x))],['Updated variance',...em.next.variances.map(x=>f(x))],['Updated mixture weight',...em.next.weights.map(x=>f(x))]])+flow(['E: calculate responsibilities','M: update weighted parameters','Repeat until convergence'])+callout('EM optimizes data likelihood; K-Means optimizes within-cluster squared distances. They do not optimize the same objective.')],
 ['Compare the real run','Use metrics that match the question','Both algorithms see the same standardized Iris features. Silhouette asks whether points are close to their own cluster and far from others. Adjusted Rand index compares the partition with known species labels.',()=>table(['Method','Silhouette','Adjusted Rand index'],[['K-Means','0.4599','0.6201'],['EM / Gaussian mixture','0.3742','0.9039']])+callout('K-Means wins on silhouette here; EM agrees more closely with species. Cluster IDs are arbitrary. Cluster 0 is not automatically species 0. The actual EM run converged in 19 iterations.')],
 ['Check your understanding','Explain both repeated procedures','K-Means alternates hard assignment and center updates. EM alternates soft responsibilities and parameter updates.',()=>quiz([['Does clustering need species labels during fitting?',['Yes','No'],1,'The labels can be used afterward for external evaluation, not as clustering inputs.'],['What does the K-Means update calculate?',['A mean of the assigned points','A random label'],0,'The mean minimizes squared distances within that assigned group.'],['What is a responsibility?',['A soft component membership','A guaranteed true species'],0,'It is a probability-like membership under the fitted mixture, not a species label.']])]
 ];}
function neighborSvg(m,raw,k){const r=predictKNN(m,raw,k),point=raw.map((x,i)=>(x-m.mean[i])/m.scale[i]),classes=[...new Set(m.trainY)].sort(),x=v=>270+v*65,y=v=>155-v*40;return `<svg viewBox="0 0 560 320" class="learn-svg" role="img" aria-label="Training flowers, query point and its ${k} nearest neighbors projected onto two features">${r.neighbors.map(n=>`<line x1="${x(point[0])}" y1="${y(point[1])}" x2="${x(m.trainX[n.index][0])}" y2="${y(m.trainX[n.index][1])}" stroke="#9bb4df" stroke-dasharray="4 3"/>`).join('')}${m.trainX.map((p,i)=>`<circle cx="${x(p[0])}" cy="${y(p[1])}" r="${r.neighbors.some(n=>n.index===i)?7:4}" fill="${[B,A,P][classes.indexOf(m.trainY[i])]}" fill-opacity=".7" stroke="white"/>`).join('')}<path d="M${x(point[0])-8} ${y(point[1])}h16m-8-8v16" stroke="#122d59" stroke-width="4"/><text x="${x(point[0])+12}" y="${y(point[1])-10}" font-size="12">New flower</text><text x="280" y="306" text-anchor="middle" font-size="12">First two standardized features shown; distances use all four.</text></svg>`;}
function knnSteps(){const s=modelState(6),m=lab.models.knn,raw=m.default,r=predictKNN(m,raw,s.k);return [
 ['Ask similar examples','A new flower asks its neighbors','KNN stores labelled training examples. At prediction time, the closest examples vote for the new flower’s class.',()=>flow(['New measurements','Find nearby training records','Let neighbors vote','Predict a species'])+table(['Feature','New flower'],lab.datasets.iris.columns.slice(0,4).map((c,i)=>[c,raw[i]]))],
 ['Keep test flowers unseen','Store 90 examples; hide 60','The program uses 90 labelled flowers for training and evaluates predictions on a separate 60. Only training records are eligible neighbors.',()=>splitGrid(90,60)+callout('The input flower in this walkthrough comes from the held-out split. It is not included among its own training neighbors.')],
 ['Make scales comparable','Distance should not be dominated by units','Standardization subtracts the training mean and divides by the training standard deviation. The same transformation is applied to a new flower.',()=>table(['Feature','Raw x','Training mean','Training standard deviation','Standardized x'],lab.datasets.iris.columns.slice(0,4).map((c,i)=>[c,raw[i],f(m.mean[i]),f(m.scale[i]),f((raw[i]-m.mean[i])/m.scale[i])]))+formula('Standardization','z = (x − training mean) / training standard deviation')+callout('Fit the scaler on training rows only. Fitting it on all records would let test information affect the model.')],
 ['Measure distances','Find the nearest records in four dimensions','Euclidean distance combines the difference in every standardized feature. The plot is a two-feature projection to help you see the idea.',()=>neighborSvg(m,raw,3)+table(['Training CSV row','Species','Distance'],predictKNN(m,raw,5).neighbors.map(n=>[n.row,n.label,f(n.distance)]))+formula('Four-feature distance','d = √[(z₁−t₁)² + (z₂−t₂)² + (z₃−t₃)² + (z₄−t₄)²]')],
 ['Let K neighbors vote','Change K and inspect the votes','K is the number of training neighbors allowed to vote. The class with the most votes wins. A deterministic tie rule handles equal vote totals.',()=>select('k','Number of neighbors',[[1,'1'],[3,'3'],[5,'5'],[7,'7']],s.k)+neighborSvg(m,raw,s.k)+table(['Class','Votes'],Object.entries(r.votes))+callout(`<b>Prediction: ${e(r.label)}.</b> K changes the vote. Do not choose K by repeatedly chasing the best result on the final test set.`)],
 ['Check all test predictions','A single example does not measure accuracy','The program uses fixed K=3 for its evaluation. It predicts all 60 held-out flowers and compares them with their known labels.',()=>flow(['57 correct','3 incorrect','57 / 60 = 95% accuracy'])+helpers.confusion([[20,0,0],[0,20,0],[0,3,17]],['setosa','versicolor','virginica'])],
 ['Check your understanding','Explain distance, scaling and voting','You can now follow a new flower from raw measurements to a majority vote.',()=>quiz([['Which records can be neighbors?',['Training records','Every record, including test answers'],0,'The held-out records must remain unseen for a fair evaluation.'],['What does K mean?',['Number of voters','Number of features'],0,'Here the feature count is four; K controls how many nearby records vote.'],['Where do the scaling mean and standard deviation come from?',['Training data','The whole dataset'],0,'Preprocessing parameters are learned from training data only.']])]
 ];}
function foldDiagram(selected=1){return `<div class="learn-folds" role="img" aria-label="Five validation rounds, each holding out a different fold">${[1,2,3,4,5].map(round=>`<div class="learn-fold-round ${round===selected?'selected':''}"><b>Round ${round}</b>${[1,2,3,4,5].map(fold=>`<span class="${round===fold?'heldout':'training'}">Fold ${fold}<small>${round===fold?'Validate':'Train'}</small></span>`).join('')}</div>`).join('')}</div>`;}
function cvSteps(){const s=modelState(7),fold=lab.models.cv.folds[s.fold-1],all=lab.models.cv.folds;return [
 ['Why test more than once?','One lucky split can mislead us','A model can memorize training examples and still fail on new ones. Cross validation checks it on several different held-out groups.',()=>flow(['Fit on known examples','Predict unseen examples','Compare with their labels','Repeat on another split'])+callout('Training fit and validation performance are different. A perfect score on examples already used for learning does not prove generalization.')],
 ['Make five balanced groups','Stratification preserves class balance','Iris has 150 records, 50 from each species. Five stratified folds contain 30 records each, including ten examples from each species.',()=>`<div class="learn-five-groups">${[1,2,3,4,5].map(i=>`<div><b>Fold ${i}</b><div class="learn-class-stripes"><i style="background:${B}"></i><i style="background:${A}"></i><i style="background:${P}"></i></div><span>10 + 10 + 10 = 30</span></div>`).join('')}</div>`+callout('The program shuffles with a fixed random seed before dividing into folds. This makes the split reproducible.')],
 ['Rotate the held-out group','Each fold gets one turn as validation data','In every round, four folds train a fresh model and one fold checks it. Select a round to see which group is kept out.',()=>select('fold','Inspect a round',[1,2,3,4,5].map(n=>[n,'Round '+n]),s.fold)+foldDiagram(s.fold)+`<div class="learn-number-row">${result('120','Training records this round')}${result('30','Validation records this round')}</div>`],
 ['Fit afresh each time','Do not carry a trained tree into the next round','The program creates a new entropy decision tree inside each fold. It never fits one tree on all 150 rows before validation.',()=>flow([`Exclude fold ${s.fold}`, 'Create a fresh model','Fit on the other 120 rows',`Predict fold ${s.fold}`])+callout('If a workflow needs a scaler, imputer or vocabulary, that preprocessing must also be refitted inside each training fold. The scikit-learn entropy tree in this experiment uses binary CART splits; it is not the categorical ID3 tree from experiment 1.')],
 ['Read one round’s results','Count what the model got right and wrong','The confusion matrix compares actual and predicted species. Accuracy divides correct predictions by all predictions; macro metrics first score each class and then give all classes equal weight.',()=>select('fold','Choose a fold',[1,2,3,4,5].map(n=>[n,'Fold '+n]),s.fold)+helpers.confusion(fold.matrix,lab.models.cv.classes)+table(['Metric','This fold'],[['Accuracy',pct(fold.accuracy)],['Macro precision',f(fold.precision)],['Macro recall',f(fold.recall)],['Macro F1',f(fold.f1)]])+formula('Classification metrics','Precision = TP / (TP + FP)\nRecall = TP / (TP + FN)\nF1 = 2 × precision × recall / (precision + recall)\nFor each class, treat that class as positive. Macro = mean across classes.')],
 ['Average all five rounds','Report the mean and the variation','Five scores are more informative than one. Every row has now appeared in validation exactly once and training four times.',()=>bars(all.map(v=>['Fold '+v.fold,v.accuracy]))+table(['Summary','Value'],[['Mean accuracy','95.33%'],['Sample standard deviation','3.80 percentage points'],['Mean macro F1','0.9531']])+formula('Mean accuracy',`(${all.map(v=>f(v.accuracy)).join(' + ')}) / 5 ≈ 0.9533`)+callout('The standard deviation describes variation between these folds; it is not automatically a confidence interval. If cross validation is used for tuning, reserve a separate final test set or use a suitable nested evaluation.')],
 ['Check your understanding','Describe the complete evaluation cycle','You can explain why five fresh fits are needed and what the final mean summarizes.',()=>quiz([['How often is each row validated?',['Once','Five times'],0,'Each row belongs to one held-out fold, but it is used for training in the other four rounds.'],['How many models are fitted?',['One full-data model','Five fresh models'],1,'A model is trained separately inside each fold.'],['What does macro averaging do?',['Gives each class equal weight','Ignores wrong predictions'],0,'First compute per-class scores, then average them without weighting by class size.']])]
 ];}
function notebookDiagram(ran){return `<div class="learn-notebook"><div class="learn-notebook-top">Notebook illustration <span>Python runtime</span></div><div class="learn-notebook-markdown"><b>My first computing experiment</b><p>This text cell explains what the next code cell will do.</p></div><div class="learn-notebook-cell"><button class="learn-run" data-learn-action="cell" aria-label="Run the illustrated code cell">▶</button><pre>2 + 3</pre></div><div class="learn-cell-output" aria-live="polite">${ran?'5':'Click ▶ to show the result.'}</div></div>`;}
function colabSteps(){const s=modelState(8);return [
 ['Meet a notebook','Keep explanation, code and output together','Google Colab hosts a Python notebook in the browser. A notebook contains cells. A text cell explains an idea; a code cell runs instructions and displays their result.',()=>flow(['Write an explanation','Run a code cell','Read its output','Save the notebook'])+callout('The examples in this learning panel are browser demonstrations. To run the actual Python programs, open the downloadable notebook in Google Colab.')],
 ['Run a simple cell','Input and output are different parts','The code 2 + 3 is the input. The number 5 is its output. Click the run symbol in this notebook illustration.',()=>notebookDiagram(s.matrixDone)+callout('In Colab, Shift+Enter runs the selected cell. Cells share runtime variables, so running later cells before their setup can cause missing-variable errors.')],
 ['Know your libraries','Each tool has a different job','A library is a collection of reusable code. You import it before calling its functions.',()=>flow(['NumPy → arrays and arithmetic','pandas → labelled tables','scikit-learn → models and evaluation'])+table(['Python statement','What it provides'],[['import numpy as np','Use np for numerical arrays'],['import pandas as pd','Use pd for tables and CSV files'],['from sklearn.datasets import load_iris','Load the example flower dataset']])],
 ['Follow a matrix operation','Matrix multiplication is not elementwise multiplication','For A = [[1,2],[3,4]], NumPy’s A @ A multiplies rows by columns. Follow each entry below.',()=>table(['Output entry','Calculation','Result'],[['Row 1, column 1','1×1 + 2×3',7],['Row 1, column 2','1×2 + 2×4',10],['Row 2, column 1','3×1 + 4×3',15],['Row 2, column 2','3×2 + 4×4',22]])+flow(['A: [[1,2],[3,4]]','A @ A','[[7,10],[15,22]]'])+callout('NumPy A * A would instead square each individual element. Use “Try it yourself” to edit the matrix.')],
 ['Create and save a table','CSV is a simple way to store rows','The program creates three student marks, calculates their mean, and saves them as colab_demo.csv. Reading the CSV back checks that the table survived the round trip.',()=>table(['Student','Marks'],[['A',78],['B',85],['C',92]])+flow(['Mean = (78+85+92)/3','85 marks','Save and reload CSV'])+`<button class="button" data-learn-action="csv">Download the demonstration CSV</button>`+formula('Equivalent Python','frame.to_csv("colab_demo.csv", index=False)\nreloaded = pd.read_csv("colab_demo.csv")')],
 ['Try the ML workflow','The notebook connects all earlier ideas','The demonstration loads Iris, separates a training set from a test set, fits a classifier and compares its predictions with the hidden test labels.',()=>splitGrid(120,30)+flow(['Load flower measurements','Fit on 120 examples','Predict 30 held-out examples','Accuracy: 96.67%'])+callout('A CPU runtime is sufficient for these labs. A GPU is not automatically faster for every small machine-learning task.')],
 ['Keep the work you need','Notebook storage and runtime storage are different','The notebook is the saved document. Temporary runtime files and variables belong to the current machine session. Save or download results you need to keep.',()=>flow(['Notebook document → save a copy','Runtime variables → temporary','Result files → download or copy to Drive'])+`<p class="learn-prose"><a class="link-arrow" href="https://research.google.com/colaboratory/faq.html" target="_blank" rel="noopener">Read the official Colab FAQ ↗</a></p>`+callout('Resource availability and runtime duration vary. Drive mounting and file pickers require your interaction in a real Colab session; this app does not authorize access to your Drive.')],
 ['Check your understanding','You are ready to open the notebook','Download the notebook from Lab resources, run setup and data cells first, and then run one experiment at a time.',()=>quiz([['Which cell explains an idea without running Python?',['A text / Markdown cell','A code cell'],0,'Markdown cells hold explanations; code cells hold executable instructions.'],['Is A @ A the same as A * A in NumPy?',['Yes','No'],1,'@ performs matrix multiplication; * multiplies individual matching entries.'],['Can temporary runtime files be assumed to stay forever?',['Yes','No'],1,'Save or download important results; managed runtime storage is temporary.']])]
 ];}
function stepsFor(id){return ({1:id3Steps,2:nbSteps,3:docSteps,4:bnSteps,5:clusterSteps,6:knnSteps,7:cvSteps,8:colabSteps}[id])();}
function render(){const s=modelState(activeId),steps=stepsFor(activeId);s.step=Math.max(0,Math.min(steps.length-1,Number(s.step)||0));const [name,heading,intro,visual]=steps[s.step],foundation=foundations[activeId];host.innerHTML=`<div class="learning-home"><section class="learning-intro"><div><span class="learn-kicker">START HERE · NO MACHINE-LEARNING EXPERIENCE NEEDED</span><h2>Understand the idea. See every step.</h2><p>${foundation[3]}</p></div><button class="button" data-learn-action="restart">Start over</button></section><div class="learn-foundations">${[['The goal',foundation[0]],['What goes in',foundation[1]],['What comes out',foundation[2]]].map(([label,value])=>`<div><span>${label}</span><b>${value}</b></div>`).join('')}</div><details class="learn-glossary"><summary>New to machine learning? Learn the basic words first.</summary><dl>${glossary.map(([term,meaning])=>`<div><dt>${term}</dt><dd>${meaning}</dd></div>`).join('')}</dl></details><div class="learn-progress"><span>STEP ${s.step+1} OF ${steps.length}</span><span>Your place is saved on this device</span><div><i style="width:${(s.step+1)/steps.length*100}%"></i></div></div><div class="lesson-layout"><nav class="lesson-steps" aria-label="Learning steps">${steps.map(([label],i)=>`<button data-lesson-step="${i}" ${i===s.step?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${label}</button>`).join('')}</nav><section class="lesson-content" aria-label="Current lesson step"><div class="lesson-step-title"><span>${name}</span><h3 tabindex="-1">${heading}</h3><p>${intro}</p></div><div class="lesson-visual-content">${visual()}</div><div class="lesson-navigation"><button class="button" data-learn-action="previous" ${s.step===0?'disabled':''}>← Previous</button><span>${s.step+1} / ${steps.length}</span>${s.step<steps.length-1?`<button class="button primary" data-learn-action="next">Next step →</button>`:'<button class="button primary" data-tab="interactive">Try the experiment →</button>'}</div></section></div><div class="learn-sources">${activeId===1?'ID3 learning order and practice tables adapted from the supplied “ID3 Complete Revision With Six PYQs and Answers” guide (pp. 2–20). Calculations are recomputed from the shown data.':activeId===2||activeId===3?'<a href="https://scikit-learn.org/stable/modules/naive_bayes.html" target="_blank" rel="noopener">Reference: scikit-learn Naive Bayes documentation ↗</a>':activeId===5?'<a href="https://scikit-learn.org/stable/modules/mixture.html" target="_blank" rel="noopener">Reference: scikit-learn Gaussian mixture documentation ↗</a>':activeId===7?'<a href="https://scikit-learn.org/stable/modules/cross_validation.html" target="_blank" rel="noopener">Reference: scikit-learn cross-validation documentation ↗</a>':'Worked examples are calculated in this app. Small illustrative examples are labelled separately from the captured Python experiment results.'}</div></div>`;const stepNav=host.querySelector('.lesson-steps'),selected=stepNav?.querySelector('[aria-current=step]');if(selected&&stepNav.scrollWidth>stepNav.clientWidth)stepNav.scrollLeft=selected.offsetLeft-stepNav.offsetLeft-(stepNav.clientWidth-selected.clientWidth)/2;save();}
function move(step){modelState(activeId).step=step;render();host.querySelector('.lesson-step-title h3')?.focus({preventScroll:true});host.querySelector('.learn-progress')?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
export function mountLearning(panel,data,id,ui){lab=data;helpers=ui;host=panel;activeId=id;controller?.abort();controller=new AbortController();const signal=controller.signal;render();host.addEventListener('click',event=>{const step=event.target.closest('[data-lesson-step]');if(step){move(Number(step.dataset.lessonStep));return;}const q=event.target.closest('[data-learn-quiz]');if(q){const s=modelState(activeId);s.answers??={};s.answers[q.dataset.learnQuiz]=Number(q.dataset.answer);render();return;}const action=event.target.closest('[data-learn-action]')?.dataset.learnAction,s=modelState(activeId);if(action==='previous')move(s.step-1);if(action==='next')move(s.step+1);if(action==='restart'){s.step=0;s.answers={};s.trace=0;render();}if(action==='trace-next'){s.trace++;render();}if(action==='trace-reset'){s.trace=0;render();}if(action==='solution'){s.solution=!s.solution;s.practiceOpen=true;render();}if(action==='cell'){s.matrixDone=true;render();}if(action==='csv'){helpers.downloadText('student,marks\nA,78\nB,85\nC,92\n','colab_demo.csv','text/csv');}},{signal});host.addEventListener('change',event=>{const name=event.target.dataset.learnControl;if(!name)return;const s=modelState(activeId);s[name]=['treeDepth','gaussFeature','k','fold','practice'].includes(name)?Number(event.target.value):event.target.value;if(name.startsWith('trace'))s.trace=0;if(name==='practice'){s.solution=false;s.practiceOpen=true;}render();},{signal});host.addEventListener('input',event=>{if(event.target.dataset.learnControl==='entropyYes'){modelState(1).entropyYes=Number(event.target.value);host.querySelector('#entropy-live').innerHTML=entropySandbox();save();}},{signal});}
export const lessonStepCounts={1:9,2:8,3:8,4:8,5:8,6:7,7:7,8:8};
